package kz.atu.inventory;
import javafx.collections.*;import javafx.collections.transformation.*;import javafx.fxml.*;import javafx.scene.*;import javafx.scene.control.*;import javafx.scene.input.*;import javafx.stage.*;import java.io.IOException;import java.util.*;
public class MainController {
 @FXML private TableView<Product> table;@FXML private TableColumn<Product,Number> idCol,qtyCol,priceCol;@FXML private TableColumn<Product,String> nameCol,catCol;@FXML private TextField searchField;@FXML private ComboBox<String> categoryBox;@FXML private Label statusLabel,summaryLabel;
 private final ObservableList<Product> items=FXCollections.observableArrayList(); private FilteredList<Product> filtered;
 @FXML private void initialize(){idCol.setCellValueFactory(v->v.getValue().idProperty());nameCol.setCellValueFactory(v->v.getValue().nameProperty());catCol.setCellValueFactory(v->v.getValue().categoryProperty());qtyCol.setCellValueFactory(v->v.getValue().quantityProperty());priceCol.setCellValueFactory(v->v.getValue().priceProperty());priceCol.setCellFactory(c->new TableCell<>(){protected void updateItem(Number n,boolean empty){super.updateItem(n,empty);setText(empty||n==null?"":String.format("%,.0f ₸",n.doubleValue()));}});
 try{items.setAll(Store.load());}catch(IOException e){error("Не удалось загрузить данные: "+e.getMessage());}filtered=new FilteredList<>(items);table.setItems(new SortedList<>(filtered,table.comparatorProperty()));searchField.textProperty().addListener((a,b,c)->filter());categoryBox.getItems().setAll("Все категории","Электроника","Канцелярия","Аксессуары");categoryBox.setValue("Все категории");categoryBox.valueProperty().addListener((a,b,c)->filter());table.getSelectionModel().selectedItemProperty().addListener((a,b,c)->refresh());refresh();}
 public void installShortcuts(Scene scene){scene.getAccelerators().put(new KeyCodeCombination(KeyCode.N,KeyCombination.CONTROL_DOWN),this::add);scene.getAccelerators().put(new KeyCodeCombination(KeyCode.S,KeyCombination.CONTROL_DOWN),this::save);scene.getAccelerators().put(new KeyCodeCombination(KeyCode.F,KeyCombination.CONTROL_DOWN),()->searchField.requestFocus());}
 private void filter(){String q=searchField.getText().toLowerCase(Locale.ROOT).trim();String c=categoryBox.getValue();filtered.setPredicate(p->(p.getName().toLowerCase(Locale.ROOT).contains(q)||String.valueOf(p.getId()).contains(q))&&(c==null||c.equals("Все категории")||p.getCategory().equals(c)));refresh();}
 private void refresh(){summaryLabel.setText("Позиций: "+items.size()+"  |  Видно: "+(filtered==null?items.size():filtered.size())+"  |  Единиц: "+items.stream().mapToInt(Product::getQuantity).sum());statusLabel.setText("Готово. Выберите товар для операций со складом.");}
 @FXML private void add(){Product p=dialog(null);if(p!=null){if(items.stream().anyMatch(x->x.getId()==p.getId())){error("ID уже существует");return;}items.add(p);save();}}
 @FXML private void edit(){Product selected=selected();if(selected==null)return;Product p=dialog(selected);if(p!=null){int i=items.indexOf(selected);items.set(i,p);save();}}
 @FXML private void delete(){Product p=selected();if(p==null)return;Alert confirm=new Alert(Alert.AlertType.CONFIRMATION,"Удалить «"+p.getName()+"»?",ButtonType.YES,ButtonType.NO);if(confirm.showAndWait().orElse(ButtonType.NO)==ButtonType.YES){items.remove(p);save();}}
 @FXML private void receive(){changeStock(true);}@FXML private void issue(){changeStock(false);}
 private void changeStock(boolean incoming){Product p=selected();if(p==null)return;TextInputDialog d=new TextInputDialog("1");d.setTitle(incoming?"Поступление":"Списание");d.setHeaderText(p.getName()+" (остаток: "+p.getQuantity()+")");d.setContentText("Количество:");d.showAndWait().ifPresent(s->{try{int n=Integer.parseInt(s.trim());if(n<=0||(!incoming&&n>p.getQuantity()))throw new IllegalArgumentException();p.setQuantity(p.getQuantity()+(incoming?n:-n));table.refresh();refresh();save();}catch(Exception e){error("Введите положительное целое число. Списать больше остатка нельзя.");}});}
 private Product selected(){Product p=table.getSelectionModel().getSelectedItem();if(p==null)error("Сначала выберите товар в таблице.");return p;}
 private Product dialog(Product p){try{FXMLLoader l=new FXMLLoader(App.class.getResource("edit.fxml"));Parent root=l.load();EditController controller=l.getController();controller.setup(p);Stage stage=new Stage();stage.setTitle(p==null?"Добавить товар":"Редактировать товар");stage.initModality(Modality.APPLICATION_MODAL);stage.setScene(new Scene(root));stage.showAndWait();return controller.getResult();}catch(IOException e){error("Ошибка открытия формы: "+e.getMessage());return null;}}
 @FXML private void save(){try{Store.save(items);statusLabel.setText("Сохранено локально");}catch(IOException e){error("Ошибка сохранения: "+e.getMessage());}}
 @FXML private void about(){new Alert(Alert.AlertType.INFORMATION,"Учебный проект · Вариант 5 · Анваров Акрам · ИС 24-22").showAndWait();}
 private void error(String message){new Alert(Alert.AlertType.ERROR,message,ButtonType.OK).showAndWait();}
}